INSERT INTO "sqlift"."achievement" ("achievement_id", "name", "description", "achievement_img_url") VALUES (1, 'Baptism by Iron', 'Complete your first workout session', null), (2, 'Goal Setter', 'Define your first fitness goal', null), (3, 'Habit Former', 'Complete 3 workouts in a single calendar week', null), (4, 'Unstoppable', 'Maintain a 7-day consecutive workout streak', null), (5, 'Early Bird', 'Complete a workout before 7:00 AM', null), (6, 'Night Owl', 'Complete a workout after 10:00 PM', null), (7, 'Venerated Veteran', 'Complete 100 total workout sessions', null), (8, 'PR Crusher', 'Set a personal record on any exercise', null), (9, 'Volume King', 'Move over 10,000 lbs in a single session', null), (10, 'Century Club', 'Perform a set with 100 or more reps', null), (11, 'Heavy Hitter', 'Lift 315 lbs or more in a single set', null), (12, 'No Pain No Gain', 'Log a session with an average RPE of 9 or higher', null), (13, 'Socialite', 'Add your first friend', null), (14, 'Squad Goals', 'Have 5 or more confirmed friends', null), (15, 'Bio Tracker', 'Log your body measurements in 4 different weeks', null), (16, 'Transformation Start', 'Log your weight at least twice to track progress', null), (17, 'Muscle Scholar', 'Work out 5 different muscle groups in one week', null), (18, 'Tool Master', 'Use 10 different types of equipment', null), (19, 'The Architect', 'Create 10 custom workout templates', null), (20, 'Completionist', 'Complete every planned set in a full workout session', null);

INSERT INTO "sqlift"."equipment" ("equipment_id", "name", "description") VALUES (1, 'Barbell', null), (2, 'SZ-Bar', null), (3, 'Dumbbell', null), (4, 'Gym mat', null), (5, 'Swiss Ball', null), (6, 'Pull-up bar', null), (7, 'none (bodyweight exercise)', null), (8, 'Bench', null), (9, 'Incline bench', null), (10, 'Kettlebell', null), (11, 'Resistance band', null);

INSERT INTO "sqlift"."exercise" ("exercise_id", "name", "description", "is_unilateral", "instruction") VALUES (9, '2 Handed Kettlebell Swing', '<p>Two Handed Russian Style Kettlebell swing</p>', false, null), (12, 'Seated Hip Adduction', 'Starting Position: Sit on the machine with your knees inward and against the pads. Pull the pin to release the pads. Grab the handles on the sides.b', false, null), (20, 'Arnold Shoulder Press', '<p>Very common shoulder exercise.</p>
<p>&nbsp;</p>
<p>As shown here:&nbsp;https://www.youtube.com/watch?v=vj2w851ZHRM</p>', false, null), (31, 'Axe Hold', '<p>Grab dumbbells and extend arms to side and hold as long as you can</p>', false, null), (41, 'Barbell Ab Rollout', '<p>Place a barbell on the floor at your feet.</p>
<p>Bending at the waist, grip the barbell with a shoulder with overhand grip.</p>
<p>With a slow controlled motion, roll the bar out so that your back is straight.</p>
<p>Roll back up raising your hips and butt as you return to the starting position.</p>', false, null), (43, 'Barbell Hack Squats', '<p>Perform leg squats with barbell behind your legs</p>', false, null), (46, 'Barbell Lunges Standing', '<p>Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.</p>
<p>Remember to keep good posture.</p>', false, null), (48, 'Barbell Reverse Wrist Curl', '<p>Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees.</p>
<p>Curl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position.</p>', false, null), (50, 'Barbell Triceps Extension', '<p>Position barbell overhead with narrow overhand grip.</p>
<p>Lower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat.</p>', false, null), (51, 'Barbell Wrist Curl', '<p>Sitting on a bench, grab a barbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face.</p>
<p>Pause for a moment in the top position, then slowly return the barbell to the starting position.</p>
<p> </p>', false, null), (56, 'Abdominal Stabilization', '', false, null), (57, 'Bear Walk 2', '<p></p><p>-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position</p>
<p>-Move by stepping with your R palm and L foot, then your L palm and R foot.&nbsp; Basically, walk like a lumbering bear.</p>
<p>-Move as fast as you can.&nbsp; Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)</p>
<p>-Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves</p>', false, null), (71, 'Single Leg Extension', '', false, null), (73, 'Bench Press', '<p>Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.</p>
<p>If you train with a high weight it is advisable to have a <em>spotter</em> that can help you up if you can''t lift the weight on your own.</p>
<p>With the width of the grip you can also control which part of the chest is trained more:</p>
<ul>
<li>wide grip: outer chest muscles</li>
<li>narrow grip: inner chest muscles and triceps</li>
</ul>', false, null), (75, 'Benchpress Dumbbells', '<p>The movement is very similar to benchpressing with a barbell, however, the weight is brought down to the chest at a lower point.</p>
<p>Hold two dumbbells and lay down on a bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.</p>', false, null), (76, 'Bench Press Narrow Grip', '<p>Lay down on a bench, the bar is directly over your eyes, the knees form a slight angle and the feet are firmly on the ground. Hold the bar with a narrow grip (around 20cm.). Lead the weight slowly down till the arms are parallel to the floor (elbow: right angle), press then the bar up. When bringing the bar down, don''t let it down on your nipples as with the regular bench pressing, but somewhat lower.</p>', false, null), (79, 'Bent High Pulls', '<p>Bend over slightly while holding two dumbbells.  Pull the dumbbells up to your chest, keeping your elbows as high as you can.</p>', false, null), (81, 'Bent Over Dumbbell Rows', '<p>With dumbbells in hand, bend at the hip until hands hang just below the knees (similar to straight-legged-deadlift starting position). Keep upper body angle constant while contracting your lats to pull you ellbows back pinching the shoulder blades at the top. Try not to stand up with every rep, check hands go below knees on every rep.</p>', false, null), (82, 'Bent-over Lateral Raises', '<p>Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.</p>', false, null), (83, 'Bent Over Rowing', '<ol>
<li>Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.</li>
<li>Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.</li>
<li>Then inhale and slowly lower the barbell back to the starting position.</li>
<li>Repeat for the recommended amount of repetitions.</li>
</ol>', false, null), (84, 'Bent Over Rowing Reverse', '<p>The same as <em>regular</em> rowing, but holding a reversed grip (your palms pointing forwards):</p>
<p>Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise.</p>
<p>Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.</p>', false, null), (91, 'Biceps Curls With Barbell', '<p>Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.</p>
<p>Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).</p>', false, null), (92, 'Biceps Curls With Dumbbell', '<p>Hold two barbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly.</p>
<p>Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).</p>', false, null), (94, 'Biceps Curls With SZ-bar', '<p>Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.</p>
<p>Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).</p>', false, null), (95, 'Biceps Curl With Cable', '<p>Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.</p>', false, null), (112, 'Body-Ups', '<ol>
<li>Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position.</li>
<li>Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement.</li>
<li>Slowly lower your forearms back to the ground by allowing the elbows to flex.</li>
<li>Repeat as needed.</li>
</ol>', false, null), (124, 'Braced Squat', '<p>Stand with feet slightly wider than shoulder-width apart, while standing as tall as you can.</p>
<p>Grab a weight plate and hold it out in front of your body with arms straight out. Keep your core tight and stand with a natural arch in your back.</p>
<p>Now, push hips back and bend knees down into a squat as far as you can. Hold for a few moments and bring yourself back up to the starting position.</p>', false, null), (129, 'Chest Press', '', false, null), (132, 'Burpees', '<p>Jump, lay down on your chest, do a pushup then jump, repeat</p>', false, null), (135, 'Butterfly', '<p>Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.</p>', false, null), (137, 'Butterfly Narrow Grip', '<p>The movement is the same as with a regular butterfly, only that the grip is narrow:</p>
<p>Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren''t!). Go slowly back. The weights should stay all the time in the air.</p>', false, null), (139, 'Butterfly Reverse', '', false, null), (142, 'Cable External Rotation', '<p>Steps:</p>
<ol>
<li>Start off placing an extension band around a post or in a secure position where it will not release and is at elbow level.</li>
<li>Position yourself to the side of the band and with your hand that is opposite of the band, reach out and grab the handle.</li>
<li>Bring the band to your chest keeping your elbow bent in a 90 degree angle then slowly rotate your arm in a backhand motion so that the band externally rotates out</li>
<li>Continue out as far as possible so that you feel a stretch in your shoulders, hold for a count and then return back to the starting position.</li>
<li>Repeat for as many reps and sets as desired.</li>
</ol>', false, null), (145, 'Cable Woodchoppers', '<p>Set cable pulley slightly lower than chest height. Keep body facing forward with hips stable.  Grab the pulley handle, fully extend your arms and bring your arms forward and across your body. Hold for 1 second at the end of the movement and slowly return to starting position.</p>', false, null), (146, 'Calf Press Using Leg Press Machine', '<p>Put  the balls of your feet on an extended leg press pad.  Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position.</p>
<p>This exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise.</p>', false, null), (148, 'Calf Raises on Hackenschmitt Machine', '<p>Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.</p>
<p>With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.</p>', false, null), (152, 'Chin Up', 'The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.', false, null), (154, 'Chin-ups', '<p>The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person''s chin.</p>', false, null), (158, 'Close-grip Lat Pull Down', '<p>Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion.</p>', false, null), (161, 'Cross-Bench Dumbbell Pullovers', '<p>Grasp a moderately weighted dumbbell so your palms are flat against the underside of the top plates and your thumbs are around the bar. Lie on your back across a flat bench so only your upper back and shoulders are in contact with the bench. Your feet should be set about shoulder-width apart and your head should hang slightly downward. With the dumbbell supported at arm''s length directly about your chest, bend your arms about 15 degrees and keep them bent throughout the movement. Slowly lower the dumbbell backward and downward in a semicircle arc to as low a position as is comfortably possible. Raise it slowly back along the same arc to the starting point, and repeat for the required number of repetitions.</p>', false, null), (165, 'Ball crunches', '', false, null), (167, 'Crunches', '<p>Lay down on your back a soft surface, the feet are on the floor. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.</p>', false, null), (171, 'Incline Crunches', '<p>Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back.</p>', false, null), (172, 'Crunches on Machine', '<p>The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position. </p>', false, null), (173, 'Crunches With Cable', '<p>Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position.</p>', false, null), (174, 'Crunches With Legs Up', '<p>On your back, legs extended straight up, reach toward your toes with your hands and lift your shoulder blades off the ground and back.</p>', false, null), (177, 'Cycling', 'Cycling, also called bicycling or biking, is the use of bicycles for transport, recreation, exercise or sport. People engaged in cycling are referred to as cyclists, bicyclists, or bikers. Apart from two-wheeled bicycles, cycling also includes the riding of unicycles, tricycles, quadracycles, recumbent and similar human-powered vehicles.', false, null), (178, 'Deadbug', '[[https://fitnessprogramer.com/exercise/dead-bug/]]Lie on your back, with your hips and knees bent to 90°. Raise both arms toward the ceiling. Pull your lower back to the floor to eliminate the gap. Start by pressing one leg out, and tapping the heel to the floor. "As you extend one leg, exhale as much as you can, keeping your lower back glued to the floor," Dunham says. When you can’t exhale any more, pull your knee back to the starting position. Make this more difficult by holding weight in your hands, or by lowering opposite arm and leg.', false, null), (182, 'Deadhang', '<p>Deadhang performed on an edge either with or without added weight (adujst edge or weight to adjust difficulty)</p>', false, null), (184, 'Deadlifts', '<p>Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one underhand, one reverse grip.</p>
<p>Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight.</p>', false, null), (185, 'Decline Bench Press Barbell', '<p>Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.</p>', false, null), (186, 'Decline Bench Press Dumbbell', '<p>Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down.</p>', false, null), (188, 'Decline Pushups', '<p>With your feet raised approximately 30cm on a platform, align your shoulders, elbows and hands, then perform regular pushups. This emphasises the clavicular fibers of the pectoralis major.</p>', false, null), (189, 'Deficit Deadlift', '<p>Preparation</p>
<p>Stand on weight plate, bumper plate, or shallow elevated platform with loaded bar above feet. Squat down and grasp bar with shoulder width or slightly wider overhand or mixed grip.</p>
<p> </p>
<p>Execution</p>
<p>Lift bar by extending hips and knees to full extension. Pull shoulders back at top of lift if rounded. Return weights to floor by bending hips back while allowing knees to bend forward, keeping back straight and knees pointed same direction as feet. Repeat.</p>
<p> </p>
<p>Comments</p>
<p>Throughout lift, keep hips low, shoulders high, arms and back straight. Knees should point same direction as feet throughout movement. Keep bar close to body to improve mechanical leverage. Grip strength and strength endurance often limit ability to perform multiple reps at heavy resistances. Gym chalk, wrist straps, grip work, and mixed grip can be used to enhance grip. Mixed grip indicates one hand holding with overhand grip and other hand holding with underhand grip. Lever barbell jack can be used to lift barbell from floor for easier loading and unloading of weight plates.</p>
<p>Barbell Deficit Deadlift emphasizes building strength through lowest portion of Deadlift. Target muscle is exercised isometrically. Heavy barbell deadlifts significantly engages Latissmus Dorsi. See Barbell Deficit Deadlift under Gluteus Maximus. Also see Deadlift Analysis.</p>', false, null), (193, 'Diagonal Shoulder Press', '<p>You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press.</p>
<p>In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.</p>
<p>Here''s a link to a girl on a machine specialized for this exercise, to give a better description than my failing words above.</p>
<p>http://www.schnell-online.de/db_imgs/products/img/t-80400.jpg</p>', false, null), (194, 'Dips', 'A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps.', false, null), (197, 'Dips Between Two Benches', '<p>Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don''t stretch out the arms.</p>', false, null), (202, 'Dumbbell Concentration Curl', '<p>Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly.</p>', false, null), (203, 'Dumbbell Goblet Squat', '<p>Grasp dumbbell with both hands at the sides of the upper plates. Hold dumbbell in front of chest, close to torso. Place feet about shoulderwide apart, keep knees slightly bent.</p>
<p>Squat down until thighs are parallel to floor. Keep back straight, bend and move hips backward to keep knees above feet. Return, keep knees slightly flexed. Repeat.</p>
<p>Keep bodyweight on heels and look ahead or slightly above to keep back straight.</p>', false, null), (204, 'Dumbbell Incline Curl', '<li><p><b>Setup:</b> Set an adjustable bench to an incline of approximately <b>45 to 60 degrees</b>.</p></li><li><p><b>Starting Position:</b> Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip).</p></li><li><p><b>The Curl:</b> Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders.</p></li><li><p><b>Peak Contraction:</b> Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward.</p></li><li><p><b>The Descent:</b> Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps.</p></li>', false, null), (205, 'Dumbbell Lunges Standing', '<p>.</p>', false, null), (206, 'Dumbbell Lunges Walking', '<p>Take two dumbbells in your hands, stand straight, feet about shoulder wide. Take one long step so that the front knee is approximately forming a right angle. The back leg is streched, the knee is low but doesn''t touch the ground. "Complete" the step by standing up and repeat the movement with the other leg.</p>', false, null), (208, 'Dumbbells on Scott Machine', '', false, null), (211, 'Dumbbell Triceps Extension', '<p>Position one dumbbell over head with both hands under inner plate (heart shaped grip).</p>
<p>With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat.</p>', false, null), (222, 'Facepull', '<p>Attach a rope to a pulley station set at about chest level.</p>
<p>Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base.</p>
<p>Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back.</p>
<p>As you near your face, externally rotate so your knuckles are facing the ceiling.</p>
<p>Hold for one second at the top position and slowly lower.</p>', false, null), (235, 'Flutter Kicks', '<p>-Laying on the back, lift your straightened legs from the ground at a 45 degree angle. </p>
<p>-As your Left foot travels downward and nearly touches the floor, your Right foot should seek to reach a 90 degree angle, or as close to one as possible.</p>
<p>-Bring your R foot down until it nearly touches the floor, and bring your L foot upwards.  Maintain leg rigidity throughout the exercise.  Your head should stay off the ground, supported by tightened upper abdominals.</p>
<p>-(L up R down, L down R up, x2)  ^v, v^, ^v, v^ = 1 rep</p>
<p>-Primarily works the Rectus Abdominus, the hip flexors and the lower back. Secondarily works the Obliques.  Emphasis placed on the lower quadrant of the abs.</p>
<p> </p>', false, null), (237, 'Fly With Cable', '', false, null), (238, 'Fly With Dumbbells', '<p>Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.</p>', false, null), (239, 'Fly With Dumbbells, Decline Bench', '<p>The exercise is the same as with a regular bench:</p>
<p>Take two dumbbells and lay on a bench, make sure the feet are firmly on the ground and your back is not arched, but has good contact with the bench. The arms are stretched in front of you, about shoulder wide. Bend now the arms a bit and let them down with a half-circle movement to the side. Without changing the angle of the elbow bring them in a fluid movement back up.</p>', false, null), (245, 'Skullcrusher Dumbbells', '<p>Hold the dumbbells and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch arms straight up and then lean dumbbells away from your toes to a 10-20 degree angle. Keep upper arm at this angle throughout exercise. Dumbbell shall not be amed at your head, but away over your head. This will maximise gain from exercise with load on triceps all the time.</p>
<p>Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.</p>', false, null), (246, 'Skullcrusher SZ-bar', '<p>Hold the SZ-bar and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch your arms with the bar and bend them so that the bar is lowered. Just before it touches your forehead, push it up.</p>
<p>Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.</p>', false, null), (254, 'Front Raises with Plates', '', false, null), (256, 'Front Raises', '<p>To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.</p>
<p>The movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.</p>
<p>When lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.</p>
<p>A neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff.</p>', false, null), (257, 'Front Squats', '<p>This variation of the squat trains the hamstrings and gluteus maximus. It also works the back extensors and abductors.</p>', false, null), (258, 'Front pull wide', '', false, null), (259, 'Front Pull narrow', '', false, null), (260, 'Full Sit Outs', '<p>(A) Get in high plank position on your hands and toes.(B) Shift your weight to your left hand as you turn your body to the right; bend your right leg behind you and extend your right arm up. Return to the center and repeat on the opposite side. Continue, alternating sides.<strong>Make it easier:</strong> Don’t raise your arm after you bend your leg behind you.<strong>Make it harder:</strong> Balance with your arm and leg extended for two counts.</p>', false, null), (265, 'Glute Bridge', '<p>Lie on you back with your hips and knees flexed, feet on the ground. From this position, raise your butt off of the ground to a height where your body makes a straight line from your knees to your shoulders. To make the exercise more intense, you can add weight by letting a barbell rest on your hips as you complete the motion, or you can put your feet on a slightly higher surface such as a step or a bench.</p>', false, null), (268, 'Good Mornings', '', false, null), (272, 'Hammer Curls', '<li><p><b>Start:</b> Hold dumbbells at your sides with palms facing your torso.</p></li><li><p><b>Curl:</b> Lift the weights toward your shoulders while maintaining the neutral grip (like holding a hammer).</p></li><li><p><b>Squeeze:</b> Contract the biceps at the top without moving your elbows forward.</p></li><li><p><b>Lower:</b> Slowly return to the starting position with full control.</p></li>', false, null), (275, 'Hammercurls on Cable', '<p>Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms.</p>
<p>Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.</p>', false, null), (279, 'Hand Grip', '<p>chrome Hand Flex Grip to build up forearms muscles</p>', false, null), (282, 'Handstand Pushup', 'The handstand push-up (press-up) - also called the vertical push-up (press-up) or the inverted push-up (press-up) also called commandos- is a type of push-up exercise where the body is positioned in a handstand. For a true handstand, the exercise is performed free-standing, held in the air. To prepare the strength until one has built adequate balance, the feet are often placed against a wall, held by a partner, or secured in some other way from falling. Handstand pushups require significant strength, as well as balance and control if performed free-standing.', false, null), (283, 'Hanging Leg Raises', '<p>Hanging from bar or straps, bring legs up with knees extended or flexed</p>', false, null), (284, 'Hercules Pillars', '<p>Grab two cables stand in the middle so both have tension and hold</p>', false, null), (285, 'High Knee Jumps', '<p>-Start with legs slightly wider than shoulder width</p>
<p>-Drop into a bodyweight squat</p>
<p>-As you hit the bottom of the squat, explode upwards into a jump while simultaneously tucking your knees into your chest midflight.  Remain tucked until the apex of your jump.</p>
<p>-Land on both feet, making sure your knees are not locked so as to avoid excessive strain upon your joints.  Collect yourself into the next rep as quickly but under control as possible.</p>', false, null), (289, 'High Pull', '<p>Use a light barbell, perform explosive lift up starting from underneath knee cap level. Lift/raise explosively using hips, at shoulder level. Tempo: 2111</p>', false, null), (291, 'Hindu Squats', '<p>Start with your feet shoulder width apart and arms slightly behind your back.</p>
<p>As you descend towards the floor, raise your heels off the ground, while keeping your back as vertical  as possible. </p>
<p>Upon attaining the bottom position, touch the hands to the heels.</p>
<p>Then stand up ending with the heels on the ground, arms extended in front of the chest then rowing into the start position.</p>', false, null), (292, 'Hip Raise, Lying', 'Lying down on your back, with your feet flat on the floor. Raise your hips up evenly as high as you can and hold for as long as you can.', false, null), (294, 'Hip Thrust', '<p>The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort.</p>', false, null), (297, 'Hollow Hold', '<p>Get on a mat and lie on your back. Contract your abs, stretch your raise and legs and raise them (your head and shoulders are also be raised). Make sure your lower back remains in contact with the mat.</p>', false, null), (301, 'Hyperextensions', '<p>Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you''re horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles.</p>', false, null), (308, 'Incline Dumbbell Fly', '<p>Use inclined bench. Hold dumbbells straight out to your sides, elbows slightly bent. Bring arms together above you, keeping angle of elbows fixed.</p>', false, null), (310, 'Incline Dumbbell Row', '<ol>
<li>Using a neutral grip, lean into an incline bench.</li>
<li>Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.</li>
<li>Retract the shoulder blades and flex the elbows to row the dumbbells to your side.</li>
<li>Pause at the top of the motion, and then return to the starting position.</li>
</ol>', false, null), (312, 'Incline Plank With Alternate Floor Touch', '<p>Perform the plank with legs elevated, feet on a gymball. Once stabilised, slowly move one foot sideways off the ball, then make it touch the floor, then come back to starting position. Alternate with the other foot.</p>
<p>This is a core exercise.</p>', false, null), (313, 'Incline Push up', '<p>Regular push with a 30 degree incline.</p>', false, null), (314, 'Isometric Wipers', '<p>Assume push-up position, with hands slightly wider than shoulder width.</p>
<p>Shift body weight as far as possible to one side, allowing the elbow on that side to flex. </p>
<p>Reverse the motion, moving completely over to the other side.</p>
<p>Return to the starting position, and repeat for the desired number of repetitions.</p>', false, null), (319, 'Jogging', '<p>Get your shoes on, go outside and start running at a moderate pace.</p>', false, null), (320, 'Jumping Jacks', '<p>A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides</p>', false, null), (323, 'Cable Cross-over', '<p>Begin with cables at about shoulder height, one in each hand. Take a step forward so that one foot is in front of the other, for stability, and so that there is tension on the cables. Bring hands together in front of you. Try to make your hands overlap (so that the cables cross) a few inches.</p>', false, null), (331, 'Kettlebell Swings', '<p>Hold the kettlebell securely in both hands. Keep your back flat throughout the move, avoiding any rounding of the spine.Keeping your knees "soft", hinge your hips backwards, letting the kettlebell swing between your knees.</p>
<p>You want to bend from the hips as far as you can <em>without letting your back round forwards</em>. Then, snap your hips forwards quickly and standing up straight, locking your body in an upright posture.</p>
<p>The speed you do this will cause your arms and the kettlebell to swing up in front of you. Don''t try to <em>lift</em> the kettlebell with your arms. The snapping forwards of your hips will cause the kettlebell to swing forwards through momentum. Depending on the weight of the kettlebell and the speed of your hip movement, your arms will swing up to about shoulder height. At the top of this swing, let your hips hinge backwards again as the kettlebell swings back down to between your legs and the start of the next repetition.</p>', false, null), (341, 'Squats on Multipress', '', false, null), (346, 'Landmine press', '', false, null), (348, 'Lateral Raises', 'This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.', false, null), (349, 'Lateral Rows on Cable, One Armed', '<p>Set cable at waist height, start with arm across your belly and move han over and out too other side, one arm at the time.</p>', false, null), (351, 'Lateral-to-Front Raises', '<p>-(1) Perform a lateral raise, pausing at the top of the lift (2).</p>
<p>-Instead of lowering the weight, bring it to the front of your body so that you appear to be at the top position of a front raise.  You will do this by using a Pec Fly motion, maintaining straight arms. (3)</p>
<p>-Now lower the weight to your quadriceps, or, in other words, lower the dumbbells as though you are completing a Front Raise repetition. (4)</p>
<p>-Reverse the motion:  Perform a front raise (5), at the apex of the lift use a Reverse Fly motion to position the weights at the top of a Lateral Raise (6), and finally, lower the weights until your palms are essentially touching the sides of your thighs (7).  THIS IS ONE REP.</p>
<p>(1) l  <em>front view  </em>(2) -l- <em> FV  </em>  (3) l-  <em>side view</em>   (4) l  <em>SV/FV</em>   (5) l-  <em>SV  </em> (6) -l-  <em>FV  </em>  (7)  l  <em>FV/SV</em></p>', false, null), (354, 'Lat Pull Down (Leaning Back)', '<p>Lean Back, Pull into chest</p>', false, null), (355, 'Lat Pull Down (Straight Back)', '<p>Pull bar down to strenum and keep straight back.</p>', false, null), (364, 'Leg Curl', 'The leg curl, also known as the hamstring curl, is an isolation exercise that targets the hamstring muscles. The exercise involves flexing the lower leg against resistance towards the buttocks. Other exercises that can be used to strengthen the hamstrings are the glute-ham raise and the deadlift.', false, null), (365, 'Leg Curls (laying)', '<p>Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs.</p>', false, null), (366, 'Leg Curls (sitting)', '', false, null), (367, 'Leg Curls (standing)', '', false, null), (369, 'Leg Extension', 'The leg extension is a resistance weight training exercise that targets the quadriceps muscle in the legs. The exercise is done using a machine called the Leg Extension Machine. There are various manufacturers of these machines and each one is slightly different. Most gym and weight rooms will have the machine in their facility. The leg extension is an isolated exercise targeting one specific muscle group, the quadriceps. It should not be considered as a total leg workout, such as the squat or deadlift. The exercise consists of bending the leg at the knee and extending the legs, then lowering them back to the original position.', false, null), (371, 'Leg Press', 'The leg press is a weight training exercise in which the individual pushes a weight or resistance away from them using their legs.', false, null), (373, 'Leg Presses (narrow)', '<p>The exercise is very similar to the wide leg press:</p>
<p>Sit on the machine and put your feet on the platform so far apart  that you could just put another foot in between them. The feet are parallel and point up.</p>
<p>Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.</p>', false, null), (374, 'Leg Presses (wide)', '<p>Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees.</p>
<p>Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.</p>', false, null), (375, 'Leg Press on Hackenschmidt Machine', '', false, null), (376, 'Leg Raise', 'The leg raise is a strength training exercise which targets the iliopsoas (the anterior hip flexors). Because the abdominal muscles are used isometrically to stabilize the body during the motion, leg raises are also often used to strengthen the rectus abdominis muscle and the internal and external oblique muscles.', false, null), (377, 'Leg Raises, Lying', '<p>Lay down on a bench and hold onto the recliner with your hands to keep you stable. Hold your legs straight and lift them till they make an angle of about 45°. Make a short pause of 1 sec. and go slowly down to the initial position. To increase the intensity you can make a longer pause of 7 sec. every 5th time.</p>', false, null), (378, 'Leg Raises, Standing', '<p>Put your forearms on the pads on the leg raise machine, the body is hanging freely. Lift now your legs with a fast movement as high as you can, make a short pause of 1sec at the top, and bring them down again. Make sure that during the exercise your body does not swing, only the legs should move.</p>', false, null), (379, 'Leverage Machine Chest Press', '<p>Be sure to adjust seat height so that the handles are towards the bottom of your pectorals.</p>', false, null), (380, 'Leverage Machine Iso Row', '<p>Adjust seat height so that the handles are at the bottom of your pectorals or just below.</p>', false, null), (382, 'L Hold', '<p>Hold the L position for as long as possible</p>', false, null), (386, 'Diamond push ups', '', false, null), (394, 'Long-Pulley (low Row)', 'Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.', false, null), (395, 'Long-Pulley, Narrow', '<p>The exercise is the same as the regular long pulley, but with a narrow grip:</p>
<p>Sit down, put your feet on the supporting points and grab the bar with a wide grip. Pull the weight with a rapid movement towards your belly button, not upper. Keep your arms and elbows during the movement close to your body. Your shoulders are pulled together. Let the weight slowly down till your arms are completely stretched.</p>', false, null), (397, 'Low Box Squat - Wide Stance', '<p>Unrack the bar and set your stance wide, beyond your hips.  Push your hips back and sit down to a box that takes you below parallel.  Sit completely down, do not touch and go.  Then explosively stand up.  Stay tight in your upper back and torso throughout the movement.</p>', false, null), (406, 'Lying Rotator Cuff Exercise', '<p>This is an excercise for problems with the levator muscles. Primary  Infraspinatus, secondary Teres Minor.</p>
<p>Lying on side. Keep elbow on waist and in 90 dgr angle. Rotate towards stomach. Add weight as fit.</p>', false, null), (418, 'Military Press mit SZ-Bar', '<p>On an SZ-bar grip your hands on the outside of each bend and stand with your arms straight down, palms facing your legs. Pull the bar (bending your arms at the elbow) to your chest, and the push the bar above your head (arms as straight as possible). Return the bar to your chest by dropping your arms at the elbows. Return the bar to it''s origional position (stand with your arms straight down, palms facing your legs.)</p>', false, null), (423, 'Muscle up', '<p>The body is then explosively pulled up by the arms in a radial pull-up, with greater speed than a regular pull-up. When the bar approaches the upper chest, the wrists are swiftly flexed to bring the forearms above the bar. The body is leaned forward, and the elbows are straightened by activating the triceps. The routine is considered complete when the bar is at the level of the waist and the arms are fully straight.</p>
<p>To dismount, the arms are bent at the elbow, and the body is lowered to the floor, and the exercise can be repeated.</p>
<p>As a relatively advanced exercise, muscle-ups are typically first learned with an assistive kip. The legs swing (kip) up and provide momentum to assist in the explosive upward force needed to ascend above the bar. More advanced athletes can perform a strict variation of the muscle-up which is done slowly, without any kip. This variation begins with a still dead hang and uses isometric muscle contraction to ascend above the bar in a slow, controlled fashion.</p>', false, null), (427, 'Negative Crunches', '<p>Sit yourself on the decline bench and fix your legs. Cross your arms over the chest and bring with a rolling movement your upper body up, go now without a pause and with a slow movement down again. Don''t let your head move during the exercise.</p>', false, null), (439, 'Overhand Cable Curl', '<p>Hands at shoulder height, curl arms in toward head, then back out.</p>', false, null), (441, 'Overhead Squat', '<p>The barbell is held overhead in a wide-arm snatch grip; however, it is also possible to use a closer grip if balance allows.</p>', false, null), (445, 'Pause Bench', '<p>Lower the bar to your chest and pause (but do not rest) there for 2 seconds. Press back up. use the same weight you would on bench press, but perform only single reps. Total the number of reps you did in one set of bench press (if you did 3 sets of 8 do 8 sinlge pause bench reps.</p>', false, null), (448, 'Pendelay Rows', '<p>Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms</p>', false, null), (454, 'Pike Push Ups', '<p>Push Up performed from a pike position (optional to have feet elevated).</p>', false, null), (456, 'Pistol Squat', '<ol><li>Stand with feet hip-width apart, toes pointed forward, and chest tall.</li><li>Extend your leg straight out; extend both arms in front of you, at shoulder level. Brace your core and look straight ahead.</li><li>Slowly squat down.&nbsp;</li><li>(optional) pause at the bottom.&nbsp;</li></ol>
Keep your (free) leg and arms extended for the whole duration.', false, null), (458, 'Plank', '<p>Get into a position on the floor supporting your weight on your forearms and toes. Arms are bent and directly below the shoulder.&nbsp;</p>
<p>Keep your body straight at all times and hold this position as long as possible. To increase difficulty an arm or leg can be raised while performing this exercise.</p>', false, null), (465, 'Preacher Curls', '<p> Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat</p>', false, null), (468, 'Prone Scapular Retraction - Arms at Side', '<p>Lying on stomach with head on towel.</p>
<p>Stretch arms straight out to your sides.</p>
<p>Slowly lift your arms, pulling your shoulderblades together, hold for 3 seconds.</p>
<p> </p>', false, null), (475, 'Pull-ups', '<p>Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out.</p>', false, null), (477, 'Pull Ups on Machine', '', false, null), (478, 'Push Press', '<p>Clean your dumbbells onto your shoulders, palms facing in. Take a breath and brace your core.&nbsp;(picture 1)<b>&nbsp;</b>Dip at the knees and use your legs to help&nbsp;(picture 2)&nbsp;press your dumbbells overhead. Lower under control with a slow tempo to your shoulders and repeat.</p>', false, null), (484, 'Rack Deadlift', '<p>Deadlift to be done using a Smith machine or a free rack. Bar or barbell hould be just right under the knee cap level. Lift using the glutes and through the heels, then come back to starting postion with a control movement of 2 seconds.</p>
<p>This exercise targets mainly the lower back and glutes.</p>', false, null), (487, 'Rear Delt Raises', '<p>Seated on a bench bWith the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position. </p>
<p> </p>', false, null), (490, 'Renegade Row', '<p>Get into pushup position gripping some dumbbells. Perform one pushup, then drive your left elbo up, bringing the dumbell up to your body. Return the dumbell to starting position. </p>
<p>Perform another pushup and then row with the other arm to complete one rep.</p>', false, null), (493, 'Reverse Bar Curl', '<p>Hold bar with reverse (or "overhand") grip, palms facing the floor.</p>', false, null), (495, 'Reverse Curl', 'The reverse-grip barbell curl is a variation on the biceps curl where the palms face downward. The switch from an underhand to an overhand grip brings the forearm and brachialis muscles more into the exercise.', false, null), (498, 'Reverse Grip Bench Press', '<p>Upper chest focuses exercise that also works triceps</p>', false, null), (500, 'Reverse Plank', '<p>Plank with stomach towards ceiling</p>', false, null), (501, 'Ring Dips', '<p>Dips peformed on gymnastic rings.</p>', false, null), (505, 'Roman Chair', '<p>Crunches on roman chair</p>', false, null), (507, 'Romanian Deadlift', '<p>DL from top to pos 2: https://www.youtube.com/watch?v=WtWtjViRsKo</p>', false, null), (508, 'Row', 'In strength training, rowing (or a row, usually preceded by a qualifying adjective — for instance a seated row) is an exercise where the purpose is to strengthen the muscles that draw the rower''s arms toward the body (latissimus dorsi) as well as those that retract the scapulae (trapezius and rhomboids) and those that support the spine (erector spinae). When done on a rowing machine, rowing also exercises muscles that extend and support the legs (quadriceps and thigh muscles). In all cases, the abdominal and lower back muscles must be used in order to support the body and prevent back injury.', false, null), (510, 'Rowing, Lying on Bench', '', false, null), (512, 'Rowing seated, narrow grip', '<ul><li>Tighten muscles</li><li>Controlled movement</li><li>Slow movement</li><li>Keep upper body upright</li><li>Do not lean back</li><li>Pull toward chest</li></ul>', false, null), (513, 'Rowing, T-bar', '<p>The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here.</p>
<p>Grab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.</p>', false, null), (516, 'Front Wood Chop', '', false, null), (525, 'Bent Over Rowing Reverse', '', false, null), (527, 'Run', '<p>Running or jogging outside in a park, on the tracks,...</p>', false, null), (529, 'Run - Interval Training', '<p>Run and do some interval trainings such as hill repat, fartlek,..</p>', false, null), (530, 'Run - Treadmill', '<p>Run on a treadmill</p>', false, null), (537, 'Incline Bench Press - Dumbbell', '<ul>
<li>Bench should be angled anywhere from 30 to 45 degrees</li>
<li>Be sure to press dumbbells straight upward (perpendicular to the floor)</li>
</ul>', false, null), (538, 'Incline Bench Press - Barbell', '<p>To do slowly, tempo is 4010</p>', false, null), (539, 'Incline Bench Press - MP', '', false, null), (543, 'Shoulder Press, on Machine', '', false, null), (545, 'Scissors', '<p>Scissors is an abdominal exercise that strengthens the transverse abdominals, helping flatten your belly and strengthen your entire core. Scissors is not only a core strength move, but it is also a great stretch for your hamstrings and your lower back. Everyone is looking for new ways to work the core, to flatten the belly and to improve flexibility. If you learn how to do Scissors you will get everything rolled together in one move.</p>', false, null), (549, 'Seated Triceps Press', '<p>Sit down on a back (better with back support). Take a dumbbell firmly with both hands and hold it with extended arms over your head. With your palms facing upward and holding the weight of the dumbbell, slowly lower the weight behind your head.</p>
<p> </p>', false, null), (556, 'Side Bends on Machine', '', false, null), (562, 'Shotgun Row', '<ol>
<li>Attach a single handle to a low cable.</li>
<li>After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position.</li>
<li>Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go.</li>
<li>After a brief pause, return to the starting position.</li>
</ol>', false, null), (566, 'Shoulder Press, Barbell', '<p>Sit on a bench, the back rest should be almost vertical. Take a barbell with a shoulder wide grip and bring it up to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.</p>', false, null), (567, 'Shoulder Press, Dumbbells', '<p>Sit on a bench, the back rest should be almost vertical. Take two dumbbells and bring them up to shoulder height, the palms and the elbows point during the whole exercise to the front. Press the weights up, at the highest point they come very near but don''t touch. Go slowly down and repeat.</p>', false, null), (569, 'Shoulder Press, on Multi Press', '<p>The exercise is basically the same as with a free barbell:</p>
<p>Sit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don''t stretch the arms completely. Go slowly down and repeat.</p>', false, null), (570, 'Shoulder Shrug', 'The shoulder shrug (usually called simply the shrug) is an exercise in weight training used to develop the upper trapezius muscle. The lifter stands erect, hands about shoulder width apart, and raises the shoulders as high as possible, and then lowers them, while not bending the elbows, or moving the body at all. The lifter may not have as large a range of motion as in a normal shrug done for active flexibility. It is usually considered good form if the slope of the shoulders is horizontal in the elevated position.', false, null), (571, 'Shrugs, Barbells', '<p>Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.</p>
<p>When training with a higher weight, make sure that you still do the whole movement!</p>', false, null), (572, 'Shrugs, Dumbbells', '<p>Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.</p>
<p>When training with a higher weight, make sure that you still do the whole movement!</p>', false, null), (575, 'Shrugs on Multipress', '', false, null), (576, 'Side Crunch', '<p>Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus.</p>', false, null), (577, 'Side Dumbbell Trunk Flexion', '<p>AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. <em> </em>Make slow and controlled torso side flexions till you reach the angle of approximately 45°.</p>', false, null), (578, 'Side-lying External Rotation', '<p>With a weight in one hand, lie on your side opposite the weight. Keep your knees slightly bent. Hold your elbow against your side, and extend your upper arm straight ahead of you. While continuing to hold your elbow against your side, rotate your upper arm 90 degrees upwards.</p>
<p>It is helpful to place a towel under your armpit to help with the form on this exercise. Placing a support under your head for the duration of the exercise is also a good idea.</p>', false, null), (580, 'Side Plank', '<p>Works your obliques and helps stabilize your spine. Lie on your side and support your body between your forearm and knee to your feet.</p>', false, null), (583, 'Side to Side Push Ups', '<p>-start in push up position</p>
<p>-lean the body weight to the right side, and complete a push up with the chest over the right hand</p>
<p>-come back to the centered position</p>
<p>-on rep 2, lean to the left side</p>', false, null), (584, 'Single-arm Preacher Curl', '<p>Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm''s elbow.</p>', false, null), (590, 'Sitting Calf Raises', '<p>Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down.</p>', false, null), (591, 'Sit-ups', '<p>Sit on a mat, your calves are resting on a bench, the knees make a right angle. Hold your hands behind your neck. Go now up with a rolling movement of your back, you should feel how the individual vertebrae lose contact with the mat. At the highest point, contract your abs as much as you can and hold there for 2 sec. Go now down, unrolling your back.</p>
<p> </p>', false, null), (595, 'Skipping - Standard', '<p>Do a single, double footed jump for each swing of the rope.</p>
<p>Work on a smooth, rhythmical movement, bouncing lightly on the balls of your feet.</p>', false, null), (598, 'Smith Machine Close-grip Bench Press', '<p>Perform a standard bench press on the smith machine, but have your hands on the bar about shoulder width apart, and keep your elbows close to your body.</p>', false, null), (599, 'Snach', '<p>Stand with your feet at hip width and your shins against the bar. Grasp the bar at double shoulder width and, keeping your lower back flat, drive your heels into the floor to begin lifting the bar. When it''s above your knees, explosively extend your hips and shrug your shoulders. Let the momentum carry the weight overhead.</p>', false, null), (604, 'Speed Deadlift', '<p>Deadlift with short (less than one 1min) rest between sets.</p>', false, null), (607, 'Splinter Sit-ups', '<p>Lie on your back with your legs straight and arms at your sides, keeping your elbows bent at 90 degrees. As you sit up, twist your upper body to the left and bring your left knee toward your right elbow while you swing your left arm back. Lower your body to the starting position, and repeat to your right. That''s 1 rep.</p>', false, null), (614, 'Squat Jumps', '<p>Jump wide, then close</p>', false, null), (615, 'Squats', '<p>Place a barbell in a rack just below shoulder-height. Dip under the bar to put it behind the neck across the top of the back, and grip the bar with the hands wider than shoulder-width apart. Lift the chest up and squeeze the shoulder blades together to keep the straight back throughout the entire movement. Stand up to bring the bar off the rack and step backwards, then place the feet so that they are a little wider than shoulder-width apart. Sit back into hips and keep the back straight and the chest up, squatting down so the hips are below the knees. From the bottom of the squat, press feet into the ground and push hips forward to return to the top of the standing position.</p>', false, null), (616, 'Squat Thrust', 'The burpee, or squat thrust, is a full body exercise used in strength training and as an aerobic exercise. The basic movement is performed in four steps and known as a four-count burpee: Begin in a standing position. Move into a squat position with your hands on the ground. (count 1) Kick your feet back into a plank position, while keeping your arms extended. (count 2) Immediately return your feet into squat position. (count 3) Stand up from the squat position (count 4)', false, null), (621, 'Standing Bicep Curl', 'Stand holding dumbbells at shoulder width apart. Face forearm upward and keep upper arm still while raising each dumbbell up to your shoulder.', false, null), (622, 'Standing Calf Raises', '<p>Get onto the calf raises machine, you should able to completely push your calves down. Stand straight, don''t make a hollow back and don''t bend your legs. Pull yourself up as high as you can. Make a small pause of 1 - 2 seconds and go slowly down.</p>', false, null), (623, 'Standing Rope Forearm', '<p>Grab a wrist roller tool with both hands while standing with your feet about shoulder width apart. If your gym does not have a wrist roller tool, you can easily put one together. All you need is a 5 or 10 pound weight plate, a strong thin rope about 3 feet long and a 6-8 inch stick or bar. Securely fasten the rope to the middle of the bar/stick and tie the other end of the rope to the weight plate. To begin this exercise, grab the bar/stick with both hands using an overhand grip. Extend both arms straight out in front of you, parallel to the floor. Next, roll the weight up from the floor by rapidly twisting the bar/stick with your hands and wrists. Once the weight reaches the top, slowly lower the plate back to the floor by reversing the motion of your hands and wrists. Repeat (if you can!).</p>', false, null), (624, 'Stationary Bike', '<p>Ride a Stationary Bike with various tensions.</p>', false, null), (627, 'Stiff-legged Deadlifts', '<ul>
<li>Keep legs straight</li>
<li>Keep back straight</li>
</ul>', false, null), (628, 'Straight-arm Pull Down (bar Attachment)', '<p>Use the straight bar attachment on a high pulley. Grasp the two ends of the bar with your palms facing downward and your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.</p>', false, null), (629, 'Straight-arm Pull Down (rope Attachment)', '<p>Use the rope attachment on a high pulley. Grasp the two ends of the rope with your arms straight out in front of you. Pull your hands down towards your hips, while keeping your arms straight, then raise them back up to the starting position.</p>', false, null), (630, 'Sumo Deadlift', '<ol>
<li>Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.</li>
<li>Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.</li>
<li>As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.</li>
<li>Return the weight to the ground by bending at the hips and controlling the weight on the way down.</li>
</ol>', false, null), (632, 'Sumo Squats', '<p>Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder.</p>
<p>While keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting).</p>
<p>Lower yourself until your quadriceps and hamstrings are parallel to the floor.</p>
<p>Return to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel.</p>', false, null), (636, 'Superman', '<p>Lay flat on your stomach with your arms extended in front of you on the ground as your legs are lying flat. Lift both your arms and legs at the same time, as if you were flying, and contract the lower back. Make sure that you are breathing and, depending on your fitness level, hold the movement for at least two to five seconds per repetition.</p>', false, null), (650, 'Thruster', '<ol>
<li>Start by doing a front squat</li>
<li>At the top position, push the bar above your head (similar to a press)</li>
<li>Lower the bar to the shoulders</li>
</ol>', false, null), (655, 'Tricep Dumbbell Kickback', '<ol>
<li>Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.</li>
<li>Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.</li>
<li>After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.</li>
<li>Repeat the movement for the prescribed amount of repetitions.</li>
</ol>
<p><strong>Variations:</strong> This exercise can be executed also one arm at a time much like the one arm rows are performed.</p>
<p>Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip).</p>', false, null), (659, 'Triceps Extensions on Cable', '<p>Grab the cable, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Rotate your hands outwards at the very end and go back to the initial position without pause.</p>', false, null), (660, 'Triceps Extensions on Cable With Bar', '<p>Grab the bar, stand with your feet shoulder wide, keep your back straight and lean forward a little. Push the bar down, making sure the elbows don''t move during the exercise. Without pause go back to the initial position.</p>', false, null), (661, 'Triceps on Machine', 'Sit down and hold the bar firmly with your hands. Now press the weight upwards (don''t fully extend your arms) and lower it slowly again. As with other triceps exercises, it''s important not to move your upper arms.', false, null), (672, 'Trunk Rotation With Cable', '<p>Seated trunk rotation with cable </p>', false, null), (674, 'Rowing with TRX band', 'Rowing with resistance bands - Bodyweight Exercise', false, null), (675, 'Turkish Get-Up', '<p>Starting on back, move to the standing position with dumbbell in one hand.  Switch hands between reps.</p>', false, null), (683, 'Power Clean', '<p>Olympic weight lifting</p>', false, null), (684, 'Underhand Lat Pull Down', '<p>Grip the pull-down bar with your palms facing you and your hands closer than shoulder-width apart. Lean back slightly and keep your back straight. Pull the bar down towards your chest, pulling your shoulders back slightly at the end of the motion.</p>', false, null), (687, 'Overhead Press', '', false, null), (688, 'Upper External Oblique', '<p>Exercise for upper external oblique muscles</p>', false, null), (691, 'Upright Row, on Multi Press', '<p>The movements are basically the same as with an SZ-bar, but you use the bar on the multi press:</p>
<p>Stand straight, your feet are shoulder-width apart. Hold the bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.</p>', false, null), (693, 'Upright Row, SZ-bar', '<p>Stand straight, your feet are shoulder-width apart. Hold the SZ-bar with an overhand grip on your thighs, the arms are stretched. Lift the bar close to the body till your chin. The elbows point out so that at the highest point they form a V. Make here a short pause before going slowly down and repeating the movement.</p>', false, null), (694, 'Upright Row w/ Dumbbells', '<p>Feet apart at shoulder width. Nice and Slow!</p>', false, null), (695, 'V-Bar Pulldown', '<p>Pulldowns using close grip v-bar.</p>', false, null), (702, 'Calf raises, one legged', '', false, null), (711, 'Wall Handstand', '<p>Handstand against a wall for support (chest facing wall).</p>', false, null), (713, 'Wall Pushup', '<p>Pushup against a wall</p>', false, null), (716, 'Wall Slides', '<p>Stand with heels, shoulders, back of head, and hips touching the wall. Start with biceps straight out and elbows at a 90 degree angle. Straighten the arms while remaining againstthe wall without arching the back off of the wall, mimicking a shoulder press movement. </p>', false, null), (718, 'Wall Squat', '<p>Find a nice flat piece of wall and stand with your back leaning against the wall. Slowly slide down the wall while moving your feet away from it, until your thighs are parallel to the ground and both your knees and your hips are bent at a 90° angle. Cross your arms in front of your chest and hold this position for 30 seconds.</p>
<p>Variant: put a big inflated rubber ball (like a small basketball) between your knees and squeeze the ball while holding the squat position</p>', false, null), (722, 'Weighted Step-ups', '<p>box step ups w/ barbell and 45''s on each side</p>', false, null), (723, 'Wide-grip Pulldown', '<p>Lat pulldowns with a wide grip on the bar.</p>', false, null), (801, 'Dumbbell Push-Up', '<p>Normal Push-ups on Dumbbells, this brings a further range of movement</p>', false, null), (802, 'Barbell Lunges Walking', '', false, null), (803, 'One Arm Triceps Extensions on Cable', '', false, null), (804, 'Sloper hanging', '<p>Hanging on sloper holds of a fingerboard for a amount of seconds</p>', false, null), (805, 'Tricep Pushdown on Cable', 'The cable rope push-down is a popular exercise targeting the triceps muscles. It''s easy to learn and perform, making it a favorite for everyone from beginners to advanced lifters. It is usually performed for moderate to high reps, such as 8-12 reps or more per set, as part of an upper-body or arm-focused workout.', false, null), (820, 'Fingerboard 20 mm edge', 'Hang for 10 seconds on a fingerboard with a 20 mm edge', false, null), (821, 'Pullup on fingerboard', 'Pullup on a choosen edge of a fingerboard / hangboard ', false, null), (822, 'Cable Rear Delt Fly', '<p style="">The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.</p><p style=""></p><ol><li>Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.</li><li>With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.</li><li>Start the movement by moving your arms back and forth while keeping your arms straight.</li><li>Pause at the finish of the move for a brief moment before returning the handles to their starting positions.</li></ol><p></p>', false, null), (827, 'Front Plate Raise', 'The plate front raise is a variation of the dumbbell front raise where the lifter holds a weight plate between two hands, rather than using a dumbbell, barbell, or other weight. It can provide variety in a shoulder-focused muscle-building workout, or as part of an upper body or full-body circuit.
<ol><li>While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. <b>Tip</b>: The arms will remain in this position throughout the exercise. This will be your starting position.</li><li>Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction for a second. As you inhale, slowly lower the plate back down to the starting position.</li><li>Repeat for the recommended amount of repetitions.</li></ol>', false, null), (828, 'Incline Bench Reverse Fly - Hello', 'The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more.', false, null), (829, 'Rear Delt Raise', '<p>Seated on a bench with the dumbbells on the floor bend over at 45 Degrees and then slowly raise each dumbbell to shoulder height and hold for a couple seconds before lowering to the starting position.&nbsp;</p><p></p>', false, null), (851, 'Leg Extension', 'Is an isolation exercise focused on the quadriceps, which are made up of four specific muscles on the front of your thigh—the rectus femoris, vastus lateralis, vastus medialis, and vastus intermedius.', false, null), (901, 'Barbell Hip Thrust', 'Sit on the ground with a bench behind you, bending your knees so your feet are planted on the ground and holding a barbell resting below your hips. If you have a padded bar, or anything you can slip in between the bar and your body, it will go a long way to making the exercise more comfortable.', false, null), (902, 'Barbell Hip Thrust', 'Sit on the ground with a bench behind you, bending your knees so your feet are planted on the ground and holding a barbell resting below your hips. If you have a padded bar, or anything you can slip in between the bar and your body, it will go a long way to making the exercise more comfortable.', false, null), (906, 'Barbell Hip Thrust', 'Sit on the ground with a bench behind you, bending your knees so your feet are planted on the ground and holding a barbell resting below your hips. If you have a padded bar, or anything you can slip in between the bar and your body, it will go a long way to making the exercise more comfortable.', false, null), (907, 'Handstand Push Up', 'Handstands Push Up which demand high level of skill', false, null), (908, 'Zone 2 Running', 'Zone two Cardio for endurance, you should be able to speak while running', false, null), (909, 'Reverse Nordic Curl', 'Natural Leg Extension is alternative to Leg Extension machine with no equipment.&nbsp;&nbsp;', false, null), (910, 'Nordic Curl', '<p style="">The Nordic hamstring curl is one of the best lower-body exercises to&nbsp;build posterior leg strength, improve knee health, and prevent injury.</p>', false, null), (911, 'Incline Skull Crush', 'Siting in a 45 Degree Angle, using DB to do Incline Skull Crush', false, null), (912, 'Straight Bar Cable Curls', 'Standing upright in front of Cable Tower using a straight bar', false, null), (913, 'Reverse Preacher Curl (Close Grip)', 'Sitting reverse on a Biceps Bench with a close grip', false, null), (914, 'Reverse EZ Bar Cable Curls', 'Standing in front of cable tower using a SZ Bar', false, null), (915, 'BUS DRIVERS', 'Sitting with a Weight Plate, used as wheel, in both hands; raised slightly below eye level', false, null), (916, 'Smith Press', 'Sitting almost 90 degree angle, smith machine&nbsp;', false, null), (917, 'Straight Bar Cable Front Raise', 'Back to cable tower, cable between legs, SZ Bar', false, null), (918, 'Seated Dumbbell Side Lateral', 'seated slightly leaned forward at beginning of exercise', false, null), (919, 'T-Bar row', 'bent over with triangle grip, slightly bent knees', false, null), (920, 'V-BAR PULL DOWNS', 'Cable machine, leaned forward during negative, lean back during contraction', false, null), (921, 'Seated Cable Rows', '“Stay leaned forward - tuck elbows in on the negative”', false, null), (922, 'SEATED CABLE MID TRAP SHRUG', 'seated straight back, slight hold at top', false, null), (923, 'LYING DUMBBELL ROW SS SEATED SHRUG', 'laying on the stomach on a bench with slight angle', false, null), (924, 'Cable Fly', 'cable machine, two steps forward, straight back', false, null), (925, 'SMITH MACHINE SLIGHT INCLINE PRESS', 'laying under smith machine, with slight incline', false, null), (926, 'Machine chest fly', 'seated machine, straight back, slow exercise', false, null), (927, 'Suspended crossess', 'Suspension exercise with trx for chest training', false, null), (957, 'Quadriped Arm and Leg Raise', 'In this exercise, the back muscles and the muscles of the back of the leg and back of the arm are activated by lifting the crossed arm and leg at the same time in the crawling position. It also improves balance and proprioception. The movement is done symmetrically.

1. Get into a crawling posture.2. Draw your abdomen in, then raise your right leg and left arm.3. You should keep your abdomen in for 8 seconds.4. After 8 seconds, slowly lower your arm and leg.5. Then release your muscle.
', false, null), (958, 'Biceps with TRX', 'Grab the handles of the TRX straps, lean your body back, arms and legs extended, with your body positioned in a single straight line. (This is an arm exercise, not an abdominal one.)', false, null), (959, 'TRX Rows', 'This exercise serves as a lead-up to Pull Ups.', false, null), (960, 'Kettlebell Swing', 'While kettlebell swings are a full-body workout, they mostly target the muscles along the posterior chain (back of the body). The main muscles used are the glutes, hamstrings, spinal erectors, and muscles of the upper back.', false, null), (961, 'Swimming 50m sprints', '50m swimming sprints at 1min', false, null), (962, 'Elliptical', 'It improves muscle toning, strengthens the leg muscles (quads, glutes, calves), helps vascularisation and increases resistance. The elliptical is also very useful if you aim to lose weight. Teste', false, null), (974, 'Curl with kettlebell two hands', 'Stand upright and grip the kettlebell with both hands. Perform the elbow flexion motion, starting from a fully extended position until your hand reaches shoulder height. Spread your legs a little for stability and, to perform the exercise correctly, try not to push with your back or body in general. Change the weight of the kettlebell to adjust the difficulty.', false, null), (975, 'one-handed kettlebell curls', 'Standing with the kettlebell in one hand and bent at the elbow, start from a fully extended position until your hand reaches shoulder height. To perform the movement correctly, try not to push with your back or body.', false, null), (976, 'Medicine ball booklet crunch', 'Using a medicine ball as an overload will make the exercise heavier.', false, null), (977, 'Box squat', '<ol><li><b>Set up the box: </b>Position the box behind you, about 3 feet from a squat rack if you''re using a barbell. Choose a height that allows you to squat down and gently tap your glutes on the box with your back straight.</li><li><b>Stand with proper form: </b>Stand with your feet shoulder-width apart, toes pointed slightly outward. Engage your core and keep your back neutral. If using a barbell, rack it at shoulder height.</li><li><b>Lower down: </b>Sit back as if going to sit on a chair, bending your knees and lowering your hips towards the box. Keep your core tight and back straight throughout the movement.</li><li><b>Controlled descent: </b>Descend in a controlled manner until your glutes gently touch the box. Don''t plop down.</li><li><b>Pause and press up: </b>Briefly pause at the bottom with your back straight and core engaged. Then, press through your heels to drive yourself back up to the starting position.</li></ol>
Improvements in coordination, balance and endurance, toning of the leg and buttock muscles and an overall increase in bone density eliminating the risk of osteoporosis.', false, null), (978, 'Knee Raises', 'The 90° leg raise on the bar is a very intense exercise that involves all the abdominal muscles.', false, null), (979, 'Leg raises pull up bar', 'with a firm grip with both hands on the bar, raise your outstretched legs, until you reach a 90° angle with your torso.', false, null), (980, 'commando pull-ups', 'variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone,&nbsp;do not twist the torso to get back to the front, the head passes once to one side, once to the other.', false, null), (981, 'Step-ups', '<p>Starting position:</p><p>Stand facing a chair.</p><p>Steps:</p><ol><li>Step up onto the chair.</li><li>Step off the chair.</li><li>Repeat.</li></ol>', false, null), (983, 'High knees', '<p>Starting positionStand straight.</p><p>Steps:</p><ol><li>Run in place, putting knees as high up as is comfortable and switching legs at a quick pace.</li></ol>', false, null), (984, 'Lunges', '<p>Starting position:</p><p>Stand with back straight.</p><p>Steps:</p><ol><li>Take a large step forward with your left leg.</li><li>Bring your pelvis down until you almost touch the floor with your right knee.</li><li>Bring your pelvis back up.</li><li>Return to the starting position by stepping back.</li><li>Repeat, switching legs each time.</li></ol>', false, null), (985, 'Push-up rotations', '<p>Starting position:</p><p>Get into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.</p><p>Steps:</p><ol><li>Perform a standard push-up:</li></ol><p>1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position.</p><ol start="2"><li>Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor.</li><li>Repeat, changing sides at step 2 each time.</li></ol>', false, null), (986, 'Side split squats left', '<p>Starting position:</p><ol><li>Stand tall and take a wide lateral stride, just greater than shoulder width.</li></ol><p>Steps:</p><ol><li>Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot.</li><li>Push back to the starting position.</li><li>Repeat.</li></ol>', false, null), (987, 'Side split squats right', '<p>Starting position:</p><ol><li>Stand tall and take a wide lateral stride, just greater than shoulder width.</li></ol><p>Steps:</p><ol><li>Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot.</li><li>Push back to the starting position.</li><li>Repeat.</li></ol>', false, null), (988, 'Bulgarian split squats left', '<ol><li>Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.</li><li>Bend the front knee, balancing with arms until the back knee almost touches the ground.</li><li>Push back to the starting position and repeat.</li></ol>', false, null), (989, 'Bulgarian split squats right', '<ol><li>Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.</li><li>Bend the front knee, balancing with arms until the back knee almost touches the ground.</li><li>Push back to the starting position and repeat.</li></ol>', false, null), (990, 'Kneeling kickbacks', '<p>Starting position:</p><p>Get down on all fours.</p><p>Steps:</p><ol><li>Push one foot back until fully extended, concentrating on the gluteus muscles.</li><li>Stay for one second, then return to the initial position.</li><li>Repeat, alternating feet.</li></ol>', false, null), (991, 'Split squats left', '<p>Starting position:</p><p>Stand with your back straight. Take a large step forward with your left leg.</p><p>Steps:</p><ol><li>Bring your pelvis down until you almost touch the floor with your right knee.</li><li>Bring your pelvis back up.</li><li>Repeat.</li></ol>', false, null), (992, 'Split squats right', '<p>Starting position:</p><p>Stand with your back straight. Take a large step forward with your left leg.</p><p>Steps:</p><ol><li>Bring your pelvis down until you almost touch the floor with your right knee.</li><li>Bring your pelvis back up.</li><li>Repeat.</li></ol>', false, null), (993, 'Jump rope: basic jumps', '<p>Starting position:</p><p>Put your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms.</p><p>Steps:</p><ol><li>Spin only your wrists with enough force to make the rope spin.</li><li>Jump just high enough to pass the rope below your feet.</li><li>Repeat.</li></ol><p>Notes:</p><p>This exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form.</p>', false, null), (994, 'Forward arm circles', '<p>Starting position:</p><p>Stand tall with your back straight.</p><p>Steps:</p><ol><li>Keeping your arms straight, bring them in front of you, move them down, behind your back, then over your head, and back to the initial position.</li><li>Keep circling your arms as described in step 1.</li></ol>', false, null), (995, 'Backward arm circles', '<p>Starting position:</p><p>Stand tall with your back straight.</p><p>Steps:</p><ol><li>Keeping your arms straight, bring them in front of you, raise them over your head, then continue the motion behind your back and down to the initial position.</li><li>Keep circling your arms as described in step 1.</li></ol>', false, null), (996, 'Mountain climbers', '<p>Starting position:</p><p>Start in the upright push-up position, aka. the high plank position.Hands should be directly under your shoulders.Keep your head in line with your back, facing the floor.Feet should be about hip-width apart.</p><p>Steps:</p><ol><li>Move one knee toward the center of your body, towards your elbows, keeping the other leg extended.</li><li>In a quick jumping movement, straighten the bent leg out and pull the other knee toward your body.</li><li>Keep repeating step 2, alternating legs.</li></ol><p>Notes:</p><p>Throughout the exercise, your back should remain as straight as possible – avoid a hump or a sagging back.</p>', false, null), (997, '4-count burpees', '<p>Starting position:</p><p>Stand straight, feet hip-width apart.</p><p>Steps:</p><ol><li>Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.</li><li>Keeping your hands on the floor, jump your legs backward into high plank position.</li><li>Jump your feet forward to return to the squat position.</li><li>Repeat.</li></ol>', false, null), (998, 'No push-up burpees', '<p>Starting position:</p><p>Stand straight, feet hip-width apart.</p><p>Steps:</p><ol><li>Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.</li><li>Keeping your hands on the floor, jump your legs backward into high plank position.</li><li>Jump your feet forward to return to the squat position.</li><li>Jump up.</li><li>Repeat.</li></ol>', false, null), (999, 'Reverse lunges', '<p>Starting position:</p><p>Stand straight, feet hip-width apart.</p><p>Steps:</p><ol><li>Step backward with one leg so it can bend comfortably to a 90 degree angle.</li><li>Slowly bend both knees to form 90 degree angles.</li><li>Return to the starting position.</li><li>Repeat, alternating legs.</li></ol>', false, null), (1000, 'Floor dips', '<p>Starting position:</p><p>Sit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together.</p><p>Steps:</p><ol><li>Raise your hips off the ground, straightening your arms.</li><li>Bend your elbows, bringing your hips down.</li><li>Straighten your arms, returning to the previous position.</li><li>Repeat steps 2 and 3.</li></ol><p>Notes:</p><p>The exercise''s difficulty depends on how high you bring your hips.</p>', false, null), (1001, 'High plank', '<p>Starting position:</p><p>Get into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.</p><p>Steps:</p><ol><li>Maintain the starting position for the entire duration of the exercise.</li></ol>', false, null), (1002, 'Child''s pose', '<p>Starting position:</p><p>Start on all fours, knees, toes, and hands touching the ground. Your two big toes should be touching.</p><p>Steps:</p><ol><li>Move your knees so that they''re about hip-width apart.</li><li>On an exhale, move your pelvis back to sit on your heels. Your hands should still be touching the ground.</li><li>Relax your upper body, lowering your forehead to the floor and letting your hands move forward naturally.</li><li>Stay in this pose.</li></ol><p>Tips:</p><ul><li>To leave the pose, walk your arms back under your shoulders and move your upper body up into a seated position.</li></ul>', false, null), (1003, 'Kettlebell deadlifts', '<p>Starting position:</p><p>Stand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward.</p><p>Steps:</p><ol><li>Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement.</li><li>Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart.</li><li>While contacting your abs and glutes, stand straight up.</li><li>Hinge at the hips again to bring the kettlebell back down, similarly to step 1.</li><li>Repeat from step 3.</li></ol><p>Tips:</p><ul><li>Be sure you''re performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up.</li></ul>', false, null), (1004, 'Forward shoulder rotation', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Place your hands on your shoulders.</li><li>Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.</li></ol>', false, null), (1005, 'Backward shoulder rotation', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Place your hands on your shoulders.</li><li>Repeatedly rotate both shoulder joints in a circular motion at a moderate pace.</li></ol>', false, null), (1006, 'Chin tuck', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Use fingers on your chin to slowly tuck your chin in, moving your head back to align it with your spine.</li><li>Hold for 5 seconds.</li><li>Go back to normal head position and repeat.</li></ol>', false, null), (1007, 'Head turns', '<p>Starting position:</p><p>Sit or stand with your back straight and shoulders down.</p><p>Steps:</p><ol><li>Sit or stand up straight, shoulders dropped.</li><li>Turn your head to the side as far as possible. Stop when you hit a barrier and hold for 5 seconds.</li><li>Return to center position and repeat, changing sides.</li></ol>', false, null), (1008, 'Left neck stretch', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Tilt your head to the side.</li><li>Take the hand closer to your head and use it to grab your head from the other side.</li><li>Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still.</li><li>Maintain this tension until the end of the exercise.</li></ol>', false, null), (1009, 'Right neck stretch', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Tilt your head to the side.</li><li>Take the hand closer to your head and use it to grab your head from the other side.</li><li>Push with your hand against your head and with your head against your hand so that the forces balance out and your head stays still.</li><li>Maintain this tension until the end of the exercise.</li></ol>', false, null), (1010, 'Back neck stretch', '<p>Starting position:</p><p>Sit upright on a chair or a firm pillow.</p><p>Steps:</p><ol><li>Breathe out and tilt your head forward, chin to chest, putting hands behind your head.</li><li>Use your hands to pull your head down lightly and press against your hands with your head to balance out the force.</li><li>Hold for a bit.</li><li>Relax your arms and head, opening up a bit with your shoulders.</li><li>Keep repeating this from step 2 onward.</li></ol>', false, null), (1011, 'Front neck stretch', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Open mouth wide.</li><li>Slowly tilt head back with mouth opened. If you feel the need for support, clasp your hands behind your head.</li><li>Very slowly close and open your mouth.</li><li>At the end, slowly return to starting position and close mouth.</li></ol>', false, null), (1012, 'Alternating bicep curls', '<p>Starting position:</p><p>Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.</p><p>Steps:</p><ol><li>Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.</li><li>Bring the dumbbell back down until your arm is in its original relaxed position.</li><li>Repeat, switching arms.</li></ol>', false, null), (1013, 'Left levator scapulae stretch', '<p>Starting position:</p><p>Start standing up or sitting down. Turn your head to the left, around 45 degrees or just above your nipple. Place your right hand behind your back or sit on it. Take your left hand and use it to hold the back of your head. Lean your head down slightly.</p><p>Steps:</p><ol><li>After assuming the starting position, press your head against your left hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.</li></ol>', false, null), (1014, 'Right levator scapulae stretch', '<p>Starting position:</p><p>Start standing up or sitting down. Turn your head to the right, around 45 degrees or just above your nipple. Place your left hand behind your back or sit on it. Take your right hand and use it to hold the back of your head. Lean your head down slightly.</p><p>Steps:</p><ol><li>After assuming the starting position, press your head against your right hand with slight force. Your hand should press back with equal force, so that your head doesn''t move. Hold this position.</li></ol>', false, null), (1015, 'Clockwise neck circles', '<p>Starting position:</p><p>Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.</p><p>Steps:</p><p>In a slower fluid motion and with your head relaxed and not pushing in any direction:</p><ol><li>lean toward your right shoulder.</li><li>then bring your head back, facing up.</li><li>then lean toward your left shoulder.4.and back toward the starting position.</li></ol><p>Keep repeating this as part of one slower fluid motion.</p>', false, null), (1016, 'Counterclockwise neck circles', '<p>Starting position:</p><p>Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.</p><p>Steps:</p><p>In a slower fluid motion and with your head relaxed and not pushing in any direction:</p><ol><li>lean toward your left shoulder.</li><li>then bring your head back, facing up.</li><li>then lean toward your right shoulder.4.and back toward the starting position.</li></ol><p>Keep repeating this as part of one slower fluid motion.</p>', false, null), (1017, 'Neck half circles', '<p>Starting position:</p><p>Start sitting or standing. Lean your head against one of your shoulders, but don''t push.</p><p>Steps:</p><p>In one slower fluid motion and with your head relaxed and not pushing in any direction:</p><ol><li>bring your head down toward your chest.</li><li>then lean back aganst your other shoulder.</li><li>then back toward the chest again.4.and finally toward the starting position.</li></ol><p>Keep repeating this.</p>', false, null), (1018, 'Head tilts', '<p>Starting position:</p><p>Sit or stand with your back straight.</p><p>Steps:</p><ol><li>Tilt your head to one side and hold for a bit.2.Return your head to neutral position and hold for a bit.</li><li>Tilt your head to the other side and hold for a bit.</li><li>Return your head to neutral position yet again and hold for a bit.</li><li>Repeat.</li></ol>', false, null), (1019, 'Side plank right', '<p>Starting position:</p><p>Lie down on your side, with your bottom elbow at a right angle, arm sticking out. Lift your pelvis off the floor by lifting your bottom shoulder up, keeping the forearm on the floor; your head, pelvis, and feet should be in a straight line.</p><p>Steps:</p><ol><li>Hold this position.</li></ol>', false, null), (1020, 'Pistol squats right', '<ol><li>Stand on one leg, with your other leg straight and slightly forward.</li><li>Bend one knee slowly, descending into a squat and keeping your back and your other leg straight.</li><li>Slowly raise yourself from the squat, straightening the bent knee and keeping the other leg straight.</li><li>Repeat.</li></ol>', false, null), (1021, 'Calf raises, right leg', '<ol><li>Stand on the floor or on the edge of a step to increase the range of movement.&nbsp;</li><li>Raise one foot.</li><li>Lift your heel until you''re standing on your toes.</li><li><i>(variable) </i>Stay in this position for three seconds</li><li>Slowly lower your foot until you almost touch the ground with your heel - don''t slam your foot!</li></ol>', false, null), (1022, 'Single Arm Plank to Row', 'Start position as row, extend to plank and back. Finish with row and repeat', false, null), (1027, 'Elevated prayer stretch', '<b>Starting position:</b>
Kneel in front of a bench, far enough so that your torso can fit between your knees and the bench. With your back straight, place your elbows on the bench, with palms together, hands pointing up.
<b></b>
<b>Steps:</b>
<ol><li>On exhale, stretch your chest down toward the floor without moving your lower back. At the same time, bring your hands toward your shoulders, keeping palms together and elbows on the bench.</li><li>Hold for a few seconds.</li><li>On inhale, relax your back to return to the starting position.</li><li>4. Repeat.</li></ol>', false, null), (1028, 'Quadruped thoracic rotation left', '<b>Starting position:</b>
Start kneeling on all fours, knees shoulder-width apart. Place your left hand behind your head while keeping your right hand outstretched and touching the floor.

<b>Steps:</b>
<ol><li style="">On inhale, move your left elbow toward your right hand, keeping your left hand behind your head.</li><li style="">On exhale, move your left elbow to point up toward the ceiling.</li><li style="">Repeat.</li></ol>', false, null), (1029, 'Quadruped thoracic rotation right', '<p style=""><b>Starting position:</b></p><p style="">Start kneeling on all fours, knees shoulder-width apart. Place your right hand behind your head while keeping your left hand outstretched and touching the floor.</p><p style=""><b>Steps:</b></p><ol style=""><li style="">On inhale, move your right elbow toward your left hand, keeping your right hand behind your head.</li><li style="">On exhale, move your right elbow to point up toward the ceiling.</li><li style="">Repeat.</li></ol>', false, null), (1079, 'Plate twist', 'Step 1: Sit on an exercise mat with your legs extended in front of you. 
Step 2: Grasp a plate in both hands as if holding a steering wheel, arms slightly bent, and hold it in front of your abdominals. 
Step 3: With knees slightly bent, cross your ankles and slowly lift them a few inches off the floor. 
Step 4: Keep your back straight but lean backward slightly to help maintain balance. 
Step 5: Exhaling, rotate your torso (twist) to the right side and touch the end of the plate to the floor. 
Step 6: Inhale and return to the forward facing start position. 
Step 7: Exhaling, rotate your torso (twist) to the left side and touch the end of the plate to the floor. 
Step 8: Inhale and return to the forward facing start position. 
Step 9: Repeat for a full set.', false, null), (1080, 'Hindu Pushups', 'Exercise to strengthen the shoulders and pectorals. Its name is due to the fact that it begins in the Yoga position "Dog Facing Down", passing to "Cobra" but without resting the legs or torso on the ground to finally end with a normal flexion. The exercise can also be performed backwards (back to the starting position). As a variation, after doing the push-up, the hip can be raised to return to downward facing dog.', false, null), (1081, 'Shoulder dislocates', '<b>Starting position:</b>
Stand up with your back straight and a resistance band, towel, or broomstick handle in hand. With your hands straight in front of your body and the band between your hands, push your hands apart to both be at around 45 degrees from your body, thumbs facing down. If using a towel or broomstick handle instead, grab it with an overhand grip.

<b>Steps:</b>
<ol><li>Keeping your arms outstretched, rotate at the shoulders to bring your arms overhead and then down toward your glutes.</li><li>Rotate at the shoulders in the opposite direction — overhead and then toward your groin.</li><li>Repeat.</li></ol>', false, null), (1082, 'Bent over row to external rotation', '<b>Starting position:</b>
Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor.
<b></b>
<b>Steps:</b>
<ol><li>Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine.</li><li>Hold for a bit.</li><li>Rotate at your elbows to bring your hands as far up as you can.</li><li>Hold for a bit.</li><li>Rotate at your elbows back to the previous position.</li><li>Bring your arms down to the original position.</li><li>Repeat.</li></ol>', false, null), (1083, 'YWTs', '<b>Starting position:</b>
Lie down, preferably on a mat. Stretch your arms above your head in a "Y" position (arms pointing up diagonally at around 45 degrees). Your thumbs should be pointing up.

<b>Steps:</b>
<ol><li>With arms in the Y position, lift your chest slightly from the ground, creating a pull tension in your arms upward.</li><li>Hold this position for several seconds (15–30 is ideal).</li><li>Keeping your chest up, bend at your elbows to move from a Y position to a "W" position, with arms bent at the elbows and maintaining the upward tension.</li><li>Hold for around as long as with the Y position.</li><li>Still with your chest up, move to a "T" position, straightening your arms out to the side to be perpendicular to your body.</li><li>Hold for around as long as you held the W position.</li><li>Move from the T position to the W position, then from the W position to the Y position.</li><li>Repeat.</li></ol>', false, null), (1084, 'Dumbbell Floor Press', 'Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat.', false, null), (1085, 'Dumbbell Bent Over Row', '&nbsp;Hold&nbsp;your dumbbells&nbsp;at your sides and hinge at the hips until your chest is parallel to the floor, dumbbells hanging below your knees (picture 1). Keeping your elbows close to your body, row both dumbbells towards your hips (oicture 2). Squeeze your shoulder blades down and together and lower under control to the start before repeating. Avoid using momentum from your torso and focus on squeezing your back, hard.', false, null), (1086, 'Close-grip Press-ups', 'Drop into a strong plank position, bringing your hands close together until they''re almost touching.&nbsp;(picture 1)<b>&nbsp;</b>Bend your elbows to slowly bring your chest to the floor&nbsp;(picture 2). Keep your elbows close to your body as you push back up explosively. Repeat. Ensure you take your time lowering on each rep, keeping your form sharp.', false, null), (1087, 'Dumbbell Hang Power Cleans', 'On your feet, stand tall with your dumbbells, holding them at your sides. Hinge at the hips to lower them to your knees (picture 1). Stand back up with a slight jump, using the momentum to pull the dumbbells up on to your shoulders (picture 2). Stand up straight, then lower under control to your sides and repeat. Keep this fast and explosive; if your heart rate doesn’t hit the roof, you’re doing them wrong.', false, null), (1088, 'Dumbbell sumo deadlift', 'Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’&nbsp;(picture 1).<b>&nbsp;</b>Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position&nbsp;(picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells.', false, null), (1089, 'Medicine ball twist', 'In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time', false, null), (1090, 'Vpushup', 'Lift your body off the ground by pushing your arms upwards', false, null), (1091, 'Plank Shoulter Taps', 'In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand.', false, null), (1092, 'Bag training', 'Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise', false, null), (1093, 'Rowing Machine', 'Sit on a rowing machine with your back straight. ', false, null), (1094, 'Seated Bench Press', 'Set up the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition.', false, null), (1095, 'Seated bench press', 'Position the chest press machine so that the grips are aligned with your lower chest when you sit down. Make sure you''re sitting with your back flat against the seat. Grab a handle in each hand, stick your chest out, and keep your head against the headrest. Breathe deeply and slowly push the handles forward until your arms are almost fully extended. Pause just before the lockout, then slowly return the handles to the starting position. Pause just before the handles come to a complete stop and perform another repetition.', false, null), (1096, 'Abduction while standing', 'Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.', false, null), (1098, 'Seated rear delt rise', 'Seated, bent 45 deg forward. Arms fully stretched out, raise arms up to shoulder height and back down', false, null), (1099, 'Dynamic side hold', 'Sling a rubber band on a kettlebell and lift the kettlebell by the rubber band. Let it hang by your side and stand on one leg, switch leg while continuing hold. Repeat with other hand', false, null), (1100, 'Wall balls', 'Get a medicine ball, shoulder width stance, squat, thrust the ball as high as possible against the wall and catch', false, null), (1101, 'Horizontal traction isometry', 'Perform a timed isometric pull-up on the bar', false, null), (1102, 'Alternate back lunges', 'The posterior muscles of the buttocks, hamstrings, soleus and gastrocnemius are trained more', false, null), (1103, 'walking bridge', 'from a standing position with knees slightly bent and hands resting on the floor. From here, proceed forward with your hands keeping your buttocks contracted and without losing control of your lower back.', false, null), (1104, 'Walking', 'Walking outdoor or indoor, try keeping a pace of at list 100 steps per minute.', false, null), (1105, 'Seated Knee Tuck', 'Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back.', false, null), (1106, 'Seated Knee Tuck', 'Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back.', false, null), (1109, 'Cable Concentration Curl', 'The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It''s great for emphasizing the biceps peak and is often used to finish a biceps workout', false, null), (1111, 'Push-Ups | Incline', 'Inclined push-ups primarily target the chest muscles (pectoralis major and minor), but also work the triceps, shoulders, and core to a lesser extent. Because the upper body is elevated, the incline push-up places less emphasis on the triceps compared to regular push-ups, which may be beneficial for individuals looking to specifically target their chest muscles.', false, null), (1112, 'Push-Ups | Decline', 'Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position.

Unlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level.', false, null), (1113, 'Push-Ups | Parallettes', 'Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.

Parallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.

The added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level.', false, null), (1114, 'Rest (for timed workouts)', 'When creating a workout based on time, add this to add rest time in the program', false, null), (1115, '3D lunge warmup', 'As a warmup, use light dumbbells, one in each hand. Lunge in alternating directions, forward, sideways, backwards and 45 degree angles.', false, null), (1116, 'Dumbbell farmer''s carrie', 'Grab half your body weight in each hand and walk.', false, null), (1117, 'Seated Cable Row', '<ol><li>Take a seat on the machine with your feet planted, a little wider than shoulder width. Drive the heels, and squeeze the glutes. Grab onto the cable handle.</li><li>Sit up tall with a slight bend through the knees. Tighten up the abs and low back to maintain a perpendicular angle to the floor with your torso.</li><li>Roll the shoulders back and down. Squeeze them together as you row, thinking about pinching a pencil in between them. As you do this, pull the handle back towards you, landing right above your belly button.</li><li>Pause here for a moment before returning the handle, still squeezing the shoulder blades. Once you''ve returned the weight to the stack, then allow the shoulder blades to relax, without pulling the torso forward.</li><li>Repeat the movement.</li></ol>', false, null), (1119, 'Remo maquina agarre estrecho', 'Remo en máquina con barra en agarre estrecho', false, null), (1120, 'Remo maquina agarre estrecho supino', 'Remo en máquina o polea con agarre cerrado supino', false, null), (1124, 'Jalón abierto', '
